THEME = ("T12", "Cas pratiques et choix de modèle")
SOURCE = "Production de l'auteur (cas fictifs) ; références des thèmes T01 à T11 ⚠ exemples inventés"
Q = [
(2,"Une clinique veut que seuls les médecins du service concerné voient un dossier, sauf urgence déclarée. Quel modèle convient le mieux ?","ABAC ou OrBAC avec contexte d'urgence","DAC pur","Capacités seules","MAC multi-niveaux seul",
 "La règle dépend du service, de la relation de soin et d'un contexte : c'est un cas d'attributs et de contexte."),
(2,"Une startup de 8 personnes partage des documents sans classification. Quel modèle est le plus proportionné ?","DAC avec groupes simples","MAC multi-niveaux","Zero Trust complet avec micro-segmentation","OrBAC multi-sites",
 "Le besoin est simple : un DAC bien tenu avec des groupes suffit."),
(2,"Un ministère traite des documents classifiés par niveaux et compartiments. Quel modèle est approprié ?","MAC de type Bell-LaPadula","DAC pur","Capacités seules","Aucun contrôle",
 "L'information est classifiée : la politique doit être imposée par le système."),
(2,"Un cabinet de conseil ne doit pas laisser un consultant utiliser les données de deux clients concurrents. Quel modèle ?","Muraille de Chine (Brewer-Nash)","Biba","DAC pur","ReBAC",
 "Le modèle gère les conflits d'intérêts selon l'historique d'accès."),
(2,"Un ERP comptable doit empêcher qu'une même personne saisisse et valide une écriture. Quel principe applique-t-on ?","La séparation des tâches (Clark-Wilson ou RBAC avec contraintes)","Le partage de compte","L'héritage de droits","La confiance par défaut",
 "Il faut répartir saisie et validation entre deux personnes distinctes."),
(2,"Une entreprise de 300 personnes avec 12 fonctions stables veut simplifier l'administration. Quel modèle ?","RBAC","DAC pur","MAC multi-niveaux","ReBAC",
 "Les fonctions stables se traduisent bien en rôles."),
(2,"Une plateforme de partage de documents avec des millions de dossiers et d'équipes variables. Quel modèle ?","ReBAC","MAC multi-niveaux","RBAC avec un rôle par dossier","Capacités seules",
 "Les droits suivent les relations entre personnes, groupes et dossiers."),
(2,"Une banque exige qu'un accès à des données clients soit refusé depuis un appareil non géré, même avec le bon rôle. Quel modèle ?","ABAC ou accès conditionnel","DAC","MAC","Capacités",
 "Le contexte de l'appareil est un attribut de décision."),
(3,"Une PME a 40 comptes partagés « poste caisse ». Quel est le premier risque ?","Perte d'imputabilité des actions","Excès de licences","Ralentissement du réseau","Perte du logo",
 "On ne sait pas qui a fait quoi."),
(3,"Quelle première mesure corrige les comptes partagés d'un point de vente ?","Créer des comptes nominatifs ou, à défaut, tracer l'utilisation du compte partagé par poste et par badge","Supprimer les journaux","Changer le mot de passe tous les ans","Donner le mot de passe à tous",
 "On restaure l'imputabilité."),
(2,"Un stagiaire a reçu les droits d'administrateur « pour dépanner ». Que faire ?","Retirer les droits et passer par une demande approuvée et limitée dans le temps","Laisser les droits","Les doubler","Les partager",
 "Le moindre privilège et le processus d'approbation s'appliquent."),
(3,"Un employé a changé trois fois de service en cinq ans et possède maintenant 40 droits dont 22 inutiles. Quel phénomène est en cause ?","L'accumulation de privilèges lors des mobilités","Un virus","Un déni de service","Une panne",
 "Les anciens droits n'ont pas été retirés lors des mobilités."),
(3,"Combien de pourcents de ses droits cet employé possède-t-il en trop (22 sur 40) ?","55 %","22 %","40 %","45 %",
 "22 ÷ 40 = 0,55 soit 55 %."),
(3,"Après retrait des 22 droits superflus, combien de droits lui reste-t-il ?","18","22","40","62",
 "40 − 22 = 18 droits justifiés."),
(2,"Une agence compte 6 comptables, 3 RH et 4 gestionnaires, chacun ayant un seul rôle. Combien d'utilisateurs en tout ?","13","7","12","24",
 "6 + 3 + 4 = 13 utilisateurs."),
(3,"Dans cette agence, on ajoute 2 permissions au rôle Comptable. Combien d'attributions directes aurait-on dû faire sans RBAC ?","12","2","6","8",
 "2 permissions × 6 comptables = 12 attributions, contre 2 opérations sur le rôle."),
(3,"Une entreprise a 25 rôles et 200 utilisateurs qui ont chacun 2 rôles. Combien d'attributions rôle-utilisateur ?","400","25","200","225",
 "200 × 2 = 400 attributions."),
(2,"Un fichier de paie est en mode 640, propriétaire rh, groupe rh. Un utilisateur du service comptabilité peut-il le lire ?","Non","Oui","Oui, en écriture","Oui, s'il est administrateur local",
 "Les autres n'ont aucun droit (---) ; seul rh en lecture."),
(2,"Un script de sauvegarde est en mode 755, propriétaire admin. Qui peut le modifier ?","Seulement admin (et root)","Tout le monde","Tout le groupe","Aucun",
 "Le droit d'écriture n'appartient qu'au propriétaire dans le mode 755."),
(3,"Un dossier partagé est en mode 777. Quel risque principal ?","Tout utilisateur peut lire, modifier et supprimer son contenu","Il est inaccessible","Il est chiffré","Il est sauvegardé",
 "Les droits ouverts à tous détruisent la confidentialité et l'intégrité."),
(3,"Un attaquant compromet le compte « comptable » dont les droits incluent la création de fournisseurs et leur paiement. Quelle faille de conception est en jeu ?","L'absence de séparation des tâches","Le chiffrement trop fort","Les journaux trop longs","Le DAC",
 "Un seul compte peut créer un faux fournisseur puis le payer."),
(3,"Quelle mesure aurait le plus réduit l'impact d'une fraude au RIB ?","Un contrôle à deux personnes et une vérification hors-bande de tout changement de RIB","Un nouvel écran","Un mot de passe plus long","Une sauvegarde plus fréquente",
 "La validation par une autre personne et par un canal indépendant bloque la fraude."),
(2,"Un service informatique de deux personnes partage un compte administrateur. Quelle est la première correction ?","Créer deux comptes nominatifs et tracer les actions","Supprimer le compte","Changer le fond d'écran","Ajouter un troisième compte partagé",
 "L'imputabilité d'abord."),
(3,"Un administrateur lit son courrier avec son compte à privilèges et ouvre une pièce jointe piégée. Quelle conséquence ?","L'attaquant obtient directement des droits d'administrateur","Aucune","Le journal se vide","Le réseau s'arrête",
 "D'où l'usage d'un compte distinct pour l'administration."),
(2,"Quel modèle d'administration limite ce risque ?","Comptes distincts et postes d'administration dédiés","Compte unique","Compte invité","Compte partagé",
 "On isole les usages à risque des tâches privilégiées."),
(3,"Une application accepte l'accès si le jeton reçu est valide, sans vérifier l'audience du jeton. Quel risque ?","Un jeton émis pour un autre service pourrait être accepté","Le jeton est plus court","Le jeton est chiffré","L'application est plus rapide",
 "Il faut contrôler l'émetteur, la signature, la validité et le destinataire."),
(3,"Un partage Everyone en écriture est trouvé sur un serveur de fichiers. Quelle est la meilleure première action ?","Restreindre le partage au groupe concerné et analyser les journaux d'accès","Ne rien faire","Supprimer les journaux","Ajouter des utilisateurs",
 "On corrige l'exposition puis on vérifie si elle a été exploitée."),
(2,"Quelle mesure empêche la suppression des fichiers d'un autre utilisateur dans un dossier partagé en écriture sous Linux ?","Le sticky bit","Le bit setuid","Un umask 000","Un mot de passe",
 "Seul le propriétaire du fichier (ou le propriétaire du répertoire) peut le supprimer."),
(3,"Un programme root setuid contient une faille. Quelle conséquence ?","Un utilisateur peut obtenir les droits root en l'exploitant","Aucune conséquence","Le programme est chiffré","Le disque est plein",
 "Il s'exécute avec les droits de son propriétaire."),
(2,"Une entreprise veut qu'un prestataire accède à une seule application sans voir le réseau. Quelle solution ?","Un accès ZTNA ou un portail applicatif avec MFA","Un VPN donnant accès au réseau entier","Un compte administrateur","Un accès anonyme",
 "On publie l'application, pas le réseau."),
(2,"Un contrat avec un prestataire prend fin. Quelle action est indispensable ?","Désactiver ses comptes et récupérer ses accès","Rien","Augmenter ses droits","Le laisser actif un an",
 "Les accès externes doivent expirer avec le contrat."),
(3,"Quelle bonne pratique limite l'accès d'un prestataire dans le temps ?","Un compte avec date d'expiration et un parrain interne responsable","Un compte permanent","Un compte partagé avec les salariés","Un compte sans mot de passe",
 "Le parrain valide et renouvelle."),
(2,"Une règle indique : « les gestionnaires modifient les dossiers de leur agence ». Quel attribut est indispensable pour l'évaluer ?","L'agence du gestionnaire et celle du dossier","La couleur du dossier","La taille du dossier","Le jour",
 "La règle compare deux attributs."),
(3,"Une politique ABAC contient : « permis si service = Qualité » et « refusé si appareil non conforme ». Un membre de Qualité utilise un appareil non conforme. Résultat avec « deny-overrides » ?","Refusé","Permis","Indéterminé","Permis en lecture",
 "Le refus l'emporte sur la permission."),
(3,"Même cas avec « permit-overrides » ?","Permis","Refusé","Indéterminé","Refusé en lecture",
 "Une permission suffit pour l'emporter."),
(2,"Quelle approche relie un utilisateur à plusieurs applications avec une seule connexion ?","Le SSO","Le partage de mot de passe","Le VLAN","Le chiffrement de disque",
 "Le fournisseur d'identité authentifie une fois."),
(3,"Un SSO sans MFA est compromis par un mot de passe volé. Quel est l'impact ?","Toutes les applications fédérées sont exposées","Une seule application","Aucune","Seul le mail",
 "Le SSO concentre l'accès : il doit être protégé par MFA."),
(2,"Quelle règle de mot de passe moderne recommande le NIST ?","Longueur élevée, vérification contre listes compromises, pas de rotation systématique","Rotation tous les mois","Huit caractères avec symboles imposés","Question secrète",
 "Les règles de composition rigides sont déconseillées."),
(2,"Un compte de service d'une application a le droit « Administrateur du domaine ». Quelle est la correction ?","Réduire ses droits au strict nécessaire","Ne rien changer","Partager son mot de passe","Désactiver les journaux",
 "Le moindre privilège s'applique aussi aux comptes de service."),
(3,"On découvre que le journal d'audit est modifiable par les administrateurs qu'il surveille. Quel défaut ?","Le journal n'est pas protégé contre ceux qu'il contrôle","Le journal est trop petit","Le journal est chiffré","Le journal est lent",
 "On envoie les journaux vers un système indépendant en écriture seule."),
(2,"Quel événement de sécurité faut-il alerter en priorité ?","L'ajout d'un compte au groupe des administrateurs","Un changement de fond d'écran","L'ouverture d'un document public","La mise en veille",
 "Un changement de privilèges est un signal fort."),
(2,"Une entreprise veut vérifier qu'aucun salarié ne cumule saisie et validation de factures. Quel contrôle ?","Un rapport de détection des combinaisons de rôles incompatibles","Un fond d'écran","Un changement d'imprimante","Un sondage",
 "On confronte les rôles attribués à la matrice de séparation des tâches."),
(3,"Quelle limite présente un contrôle qui ne vérifie les droits qu'à la connexion ?","Il ne détecte pas un changement de contexte en cours de session","Il est trop sûr","Il est trop rapide","Il est anonyme",
 "La vérification continue répond à cette limite."),
(2,"Quel principe sous-tend la décision de désactiver un compte inactif depuis 90 jours ?","Réduire les accès non utilisés qui peuvent être abusés","Augmenter les licences","Supprimer les journaux","Changer de politique",
 "Un compte dormant est une surface d'attaque inutile."),
(2,"Quelle donnée doit figurer dans une demande de droit pour être approuvable ?","Le bénéficiaire, le droit demandé, la justification et la durée","Un fond d'écran","Le nom du serveur seulement","Le numéro de bureau",
 "Le responsable doit comprendre le besoin pour décider."),
(3,"Un responsable approuve toutes les demandes dans la minute. Quel risque ?","Une approbation sans examen qui ne protège pas","Un excès de sécurité","Un ralentissement","Une panne",
 "Il faut des contrôles pour détecter les validations automatiques."),
(3,"Quelle donnée de contexte manque à une revue qui demande « ce droit est-il toujours nécessaire ? » ?","La date du dernier usage du droit","Le nom du bureau","La couleur du badge","La météo",
 "Un droit non utilisé depuis longtemps est un candidat au retrait."),
(2,"Quelle mesure technique complète une charte interdisant le partage de mot de passe ?","Le MFA et la détection de connexions simultanées","L'affichage de la charte","La suppression des journaux","Un mot de passe commun",
 "Les contrôles techniques rendent la règle vérifiable."),
(3,"Un prestataire d'infogérance accède à vos serveurs. Quelle exigence contractuelle et technique est la plus importante ?","Comptes nominatifs, journalisation, droits limités et droit d'audit","Un compte partagé","Un accès sans traçabilité","Un mot de passe oral",
 "Le contrat et la technique doivent s'accorder."),
(2,"Quelle différence entre un accès et une autorisation ?","L'accès est ce qui est réellement possible, l'autorisation ce qui est permis par la politique","Il n'y en a pas","L'accès est secret","L'autorisation est technique",
 "Un écart entre les deux révèle une dérive ou une faille."),
(3,"Quelle différence entre droits « théoriques » et « effectifs » ?","Les effectifs résultent du cumul de groupes, d'héritages et d'exceptions réels","Ils sont identiques","Les théoriques sont les plus larges","Les effectifs sont secrets",
 "La revue doit porter sur les droits effectifs."),
(2,"Quel outil aide à visualiser les chemins d'accès dans un annuaire Windows ?","Un outil d'analyse de graphe des droits","Un lecteur de musique","Un navigateur","Un tableur vide",
 "Il révèle les chaînes d'imbrication de groupes qui donnent des droits indirects."),
(3,"Un utilisateur est membre d'un groupe A, membre du groupe B, membre du groupe « Admins ». Que montre cette chaîne ?","Il hérite des droits d'administrateur par imbrication de groupes","Il n'a aucun droit","Il est supprimé","Il est invité",
 "Les imbrications peuvent donner des privilèges non visibles au premier regard."),
(2,"Quelle conclusion tirer d'un incident où un ancien salarié a utilisé son compte actif ?","Renforcer la gestion des départs avec désactivation automatique","Supprimer les journaux","Augmenter les droits","Ne rien faire",
 "Le processus de départ doit être fiable et automatisé."),
(3,"Une revue montre que 30 comptes sur 120 sont inutilisés depuis plus d'un an. Quelle proportion cela représente-t-il ?","25 %","30 %","12 %","40 %",
 "30 ÷ 120 = 0,25 soit 25 %."),
(3,"Si on désactive ces 30 comptes, combien de comptes actifs restent-ils ?","90","30","120","150",
 "120 − 30 = 90."),
]
